<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { api } from '../services/api'
import { useDialog } from '../stores/dialog'
type Establishment={id:number;name:string;segment:string;active:number|boolean;users_count:number}
const rows=ref<Establishment[]>([]),loading=ref(false),showForm=ref(false),error=ref('')
const form=reactive({name:'',segment:'confeitaria',userName:'',email:'',password:''})
const dialog=useDialog()
async function load(){loading.value=true;try{rows.value=await api<Establishment[]>('/admin/establishments')}catch(e){error.value=e instanceof Error?e.message:'Falha ao carregar'}finally{loading.value=false}}
async function create(){error.value='';try{await api('/admin/establishments',{method:'POST',body:JSON.stringify(form)});showForm.value=false;Object.assign(form,{name:'',segment:'confeitaria',userName:'',email:'',password:''});dialog.notify('Estabelecimento e usuário criados.');await load()}catch(e){error.value=e instanceof Error?e.message:'Falha ao cadastrar'}}
async function toggle(row:Establishment){if(!await dialog.confirm(`${row.active?'Desativar':'Ativar'} o estabelecimento ${row.name}?`))return;try{await api(`/admin/establishments/${row.id}`,{method:'PATCH',body:JSON.stringify({active:!row.active})});await load();dialog.notify('Status atualizado.')}catch(e){error.value=e instanceof Error?e.message:'Falha ao alterar'}}
onMounted(load)
</script>
<template><div class="page-heading"><div><p class="eyebrow">ADMINISTRAÇÃO DA PLATAFORMA</p><h1>Estabelecimentos</h1><p class="muted">Cadastre clientes e gerencie o acesso individual de cada negócio.</p></div><button class="primary-btn" @click="showForm=!showForm">+ Novo estabelecimento</button></div>
<form v-if="showForm" class="panel inline-form" @submit.prevent="create"><div class="panel-heading"><div><h2>Cadastrar cliente</h2><p class="muted">Crie o estabelecimento e o login do responsável.</p></div></div><div class="form-grid"><label class="field span-2">Nome do estabelecimento<input v-model="form.name" required minlength="2" placeholder="Ex.: Confeitaria da Maria" /></label><label class="field">Segmento<select v-model="form.segment"><option value="confeitaria">Confeitaria</option><option value="restaurante">Restaurante</option><option value="lancheria">Lancheria</option></select></label><label class="field">Nome do responsável<input v-model="form.userName" required minlength="2" /></label><label class="field">E-mail para login<input v-model="form.email" type="email" required /></label><label class="field">Senha inicial (mín. 12 caracteres)<input v-model="form.password" type="password" required minlength="12" autocomplete="new-password" /></label></div><div class="form-actions"><button type="button" class="secondary-btn" @click="showForm=false">Cancelar</button><button class="primary-btn">Cadastrar estabelecimento</button></div></form>
<p v-if="error" class="auth-error">{{error}}</p><section class="panel table-panel"><div class="panel-heading"><div><h2>Clientes cadastrados</h2><p class="muted">{{rows.length}} estabelecimento(s)</p></div></div><div v-if="loading" class="empty-state">Carregando...</div><div v-else-if="!rows.length" class="empty-state">Nenhum estabelecimento cadastrado.</div><div v-else class="table-wrap"><table><thead><tr><th>Estabelecimento</th><th>Segmento</th><th>Usuários</th><th>Status</th><th>Ações</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.name}}</strong></td><td>{{row.segment}}</td><td>{{row.users_count}}</td><td><span class="status" :class="{inactive:!row.active}">{{row.active?'Ativo':'Inativo'}}</span></td><td><button class="secondary-btn" @click="toggle(row)">{{row.active?'Desativar':'Ativar'}}</button></td></tr></tbody></table></div></section><p class="muted">Os produtos, vendas e relatórios são gerenciados pelo próprio cliente em seu login individual.</p></template>
